// src/server.ts
import { fileURLToPath } from "url";

// src/mcp.ts
var SERVER_NAME = "octen";
var MCP_URL = "https://mcp.octen.ai/mcp";
var PREFIX = "@octen.ai/opencode-plugin: ";
var TOOL_NAME = /^[a-z][a-z_]*$/;
function parseOptions(raw) {
  if (raw === void 0) return {};
  if (typeof raw !== "object" || raw === null || Array.isArray(raw)) {
    throw new Error(`${PREFIX}options must be an object such as { "tools": ["search", "extract"] }.`);
  }
  const unknown = Object.keys(raw).filter((key) => key !== "tools");
  if (unknown.length > 0) {
    throw new Error(`${PREFIX}unknown option ${unknown.map((key) => `"${key}"`).join(", ")}. The only option is "tools".`);
  }
  const tools = raw.tools;
  if (tools === void 0) return {};
  if (!Array.isArray(tools) || tools.length === 0 || !tools.every(isToolName)) {
    throw new Error(`${PREFIX}"tools" must be a non-empty list of tool names such as "search" or "news_search".`);
  }
  return { tools: [...tools] };
}
function isToolName(value) {
  return typeof value === "string" && TOOL_NAME.test(value);
}
function buildEntry(env, options) {
  const url = options.tools === void 0 ? MCP_URL : `${MCP_URL}?tools=${options.tools.join(",")}`;
  const key = env.OCTEN_API_KEY?.trim() ?? "";
  if (key === "") return { type: "remote", url };
  return { type: "remote", url, oauth: false, headers: { "x-api-key": key } };
}
function applyConfig(cfg, entry, skillsDir) {
  cfg.mcp ??= {};
  if (cfg.mcp[SERVER_NAME] === void 0) cfg.mcp[SERVER_NAME] = entry;
  cfg.skills ??= {};
  cfg.skills.paths ??= [];
  if (!cfg.skills.paths.includes(skillsDir)) cfg.skills.paths.push(skillsDir);
}

// src/v2.ts
import { readFileSync } from "fs";
var PREFIX2 = "@octen.ai/opencode-plugin: ";
async function setupV2(ctx, env, skillFile) {
  const entry = buildEntry(env, parseOptions(ctx.options));
  const skill = parseSkill(skillFile);
  await ctx.mcp.transform((editor) => {
    if (editor.get(SERVER_NAME) === void 0) editor.set(SERVER_NAME, entry);
  });
  await ctx.skill.transform((editor) => {
    if (editor.get(skill.id) === void 0) editor.add(skill);
  });
}
function parseSkill(path) {
  const raw = readFileSync(path, "utf8").replace(/\r\n/g, "\n");
  const fence = /^---\n([\s\S]*?)\n---\n?/.exec(raw);
  if (fence === null) throw new Error(`${PREFIX2}${path} has no front matter.`);
  const fields = {};
  const lines = (fence[1] ?? "").split("\n");
  for (let i = 0; i < lines.length; i++) {
    const field = /^([\w-]+):\s*(.*)$/.exec(lines[i] ?? "");
    if (field === null) continue;
    let value = (field[2] ?? "").trim();
    if (value === ">" || value === ">-") {
      const block = [];
      while (i + 1 < lines.length && /^\s+\S/.test(lines[i + 1] ?? "")) block.push((lines[++i] ?? "").trim());
      value = block.join(" ");
    } else if (/^(["']).*\1$/.test(value)) {
      value = value.slice(1, -1);
    }
    fields[field[1] ?? ""] = value;
  }
  const name = fields["name"];
  if (name === void 0 || name === "") throw new Error(`${PREFIX2}${path} front matter has no name.`);
  const skill = { id: name, name, path, location: path, content: raw.slice(fence[0].length).trim() };
  if (fields["description"] !== void 0) skill.description = fields["description"];
  return skill;
}

// src/server.ts
var SKILLS_DIR = fileURLToPath(new URL("../skills", import.meta.url));
var SKILL_FILE = fileURLToPath(new URL("../skills/octen-search-guide/SKILL.md", import.meta.url));
async function server(_input, options) {
  const parsed = parseOptions(options);
  return {
    config: async (cfg) => {
      applyConfig(cfg, buildEntry(process.env, parsed), SKILLS_DIR);
    }
  };
}
async function setup(ctx) {
  await setupV2(ctx, process.env, SKILL_FILE);
}
var server_default = { id: "octen", server, setup };
export {
  server_default as default
};
